<?php
declare(strict_types=1);
require_once __DIR__.'/form-builder-settings.php';

function st_form_icon(string $name): string {
    $paths=['add'=>'<circle cx="12" cy="12" r="9"/><path d="M12 8v8M8 12h8"/>','preview'=>'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/>','undo'=>'<path d="M3 10h11a6 6 0 0 1 0 12M3 10l5-5M3 10l5 5"/>','redo'=>'<path d="M21 10H10a6 6 0 0 0 0 12M21 10l-5-5M21 10l-5 5"/>','link'=>'<path d="M9 15H7a4 4 0 0 1 0-8h4M15 7h2a4 4 0 0 1 0 8h-4M8 11h8"/>','image'=>'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1"/><path d="m3 17 5-5 4 4 3-6 6 7"/>','video'=>'<rect x="2" y="5" width="20" height="14" rx="2"/><path d="m10 9 5 3-5 3Z"/>','section'=>'<path d="M3 4h18v6H3zM3 14h18v6H3z"/>','text'=>'<path d="M2 5h12M8 5v15M14 10h8M18 10v10"/>','import'=>'<path d="M5 3h9l5 5v13H5V3ZM14 3v6h5M2 14h11m-4-4 4 4-4 4"/>','duplicate'=>'<rect x="8" y="3" width="12" height="15" rx="1"/><path d="M16 21H4V7"/>','delete'=>'<path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7"/>','more'=>'<circle cx="12" cy="5" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="12" cy="19" r="1"/>'];
    return '<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'.($paths[$name]??$paths['add']).'</svg>';
}

function st_form_workspace(array $event,array $fields,array $media,string $phase,array $staff,bool $draft): void {
    $games=az_event_games($fields,false);$joystick=$event['slug']==='joystick'&&empty($fields['_form_game']);$canPublish=cms_can($staff,'event','publish',$event);
    $tickets=$phase==='registration'&&az_participation_mode($fields)==='registration'?az_ticket_options81($fields,$fields['_form_game']??''):[];
    ?>
    <form class="form-builder form-workspace-editor" data-form-builder data-form-workspace data-phase="<?= $phase ?>" data-game="<?= e($fields['_form_game']??'') ?>" data-revision="<?= (int)$event['revision'] ?>" data-joystick="<?= $joystick?'1':'0' ?>" data-ticket-options="<?= e(json_encode($tickets)) ?>" novalidate>
    <?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$event['id'] ?>">
    <header class="form-workspace-top"><a class="form-workspace-back" href="/admin.php?section=event&amp;event_id=<?= (int)$event['id'] ?>&amp;edit=<?= (int)$event['id'] ?>" aria-label="Back to event setup">‹</a><span class="form-workspace-mark" aria-hidden="true"><?= st_form_icon('section') ?></span><div class="form-document-name"><strong><?= e($event['title'].(!empty($fields['_form_game_label'])?' · '.$fields['_form_game_label']:'')) ?></strong><span><?= az_participation_mode($event)==='contribution'?'Contribution':ucfirst($phase) ?> form</span></div><span class="form-save-status" data-save-status role="status"><?= $draft?'Draft restored':'Published version' ?></span><div class="form-top-actions"><button type="button" data-form-preview title="Preview form" aria-label="Preview form"><?= st_form_icon('preview') ?></button><button type="button" data-form-undo title="Undo" aria-label="Undo" disabled><?= st_form_icon('undo') ?></button><button type="button" data-form-redo title="Redo" aria-label="Redo" disabled><?= st_form_icon('redo') ?></button><button type="button" data-form-link data-url="/event.php?name=<?= e($event['slug']) ?>" title="Copy event link" aria-label="Copy event link"><?= st_form_icon('link') ?></button><button type="button" class="quiet-button" data-save-draft>Save draft</button><button type="submit" class="primary-button" <?= !$canPublish?'disabled title="An editor can publish your saved draft"':'' ?>>Publish</button></div></header>
    <nav class="form-workspace-tabs" role="tablist" aria-label="Form editor"><button type="button" role="tab" id="workspace-questions-tab" aria-controls="workspace-questions" aria-selected="true" data-workspace-tab="questions">Questions</button><button type="button" role="tab" id="workspace-responses-tab" aria-controls="workspace-responses" aria-selected="false" tabindex="-1" data-workspace-tab="responses">Responses</button><button type="button" role="tab" id="workspace-settings-tab" aria-controls="workspace-settings" aria-selected="false" tabindex="-1" data-workspace-tab="settings">Settings</button></nav>
    <main class="form-workspace-main" data-form-panel="<?= $phase ?>">
    <div id="workspace-questions" role="tabpanel" aria-labelledby="workspace-questions-tab" data-workspace-pane="questions">
    <div class="form-builder-header"><label class="field"><span class="sr-only">Form title</span><textarea name="<?= $phase ?>_title" aria-label="Form title" maxlength="200" rows="1" placeholder="Untitled form"><?= e($fields[$phase.'_title']??$event['title'].' registration') ?></textarea></label><label class="field"><span class="sr-only">Form description</span><textarea name="<?= $phase ?>_intro" aria-label="Form description" maxlength="5000" rows="1" placeholder="Form description"><?= e($fields[$phase.'_intro']??'') ?></textarea></label></div>
    <div class="form-builder-list" data-question-list><?php foreach(az_registration_fields($fields,$phase) as $i=>$field)st_registration_field_row((string)$i,$field,$phase,$games,$joystick,$media,$tickets); ?></div><p class="form-builder-empty" data-question-empty hidden>Add your first question using the + button.</p><span class="form-item-count" data-question-count></span>
    <aside class="form-side-tools" aria-label="Insert form content"><?php foreach(['add'=>['Add question','data-question-add="'.$phase.'"'],'import'=>['Import questions','data-import-open'],'text'=>['Add title and description','data-add-kind="description"'],'image'=>['Add image or payment QR','data-add-kind="image"'],'video'=>['Add video','data-add-kind="video"'],'section'=>['Add section','data-add-kind="section"']] as $icon=>[$label,$attr]): ?><button type="button" <?= $attr ?> title="<?= $label ?>" aria-label="<?= $label ?>"><?= st_form_icon($icon) ?></button><?php endforeach; ?><button type="button" data-add-payment title="Add payment QR and screenshot questions" aria-label="Add payment QR and screenshot questions">₹</button></aside>
    <details class="form-template-tools"><summary>Templates</summary><button class="quiet-button" type="button" data-form-export>Download form template</button><label class="quiet-button form-import-button">Import questions<input type="file" accept="application/json,.json" data-form-import form="template-upload-only"></label></details>
    </div>
    <div id="workspace-responses" role="tabpanel" aria-labelledby="workspace-responses-tab" data-workspace-pane="responses" hidden><section class="form-builder-header"><h2>Responses</h2><?php
    if($phase==='registration'&&az_participation_mode($event)==='registration'&&cms_can($staff,'payments','view')){
        $db=cms_db();$where="o.event_id=? AND o.environment='live' AND o.provider='form'";$params=[$event['id']];
        if(!empty($fields['_form_game'])){$where.=($db->getAttribute(PDO::ATTR_DRIVER_NAME)==='sqlite'?" AND json_extract(o.snapshot,'$.game_id')=?":" AND JSON_UNQUOTE(JSON_EXTRACT(o.snapshot,'$.game_id'))=?");$params[]=$fields['_form_game'];}
        $q=$db->prepare("SELECT o.*,p.name,p.email FROM az_orders o JOIN az_participants p ON p.id=o.participant_id WHERE $where ORDER BY o.id DESC LIMIT 50");$q->execute($params);$responses=$q->fetchAll();
        $count=$db->prepare("SELECT COUNT(*) FROM az_orders o WHERE $where");$count->execute($params);echo '<p>'.(int)$count->fetchColumn().' responses · latest 50 shown</p><a class="primary-button" href="/admin.php?section=payments&amp;event_id='.(int)$event['id'].'">Review responses & approve tickets ↗</a>';if($responses)st_form_response_table($responses);else echo '<p class="help">Submitted forms and private uploads will appear here.</p>';
    }else echo '<p class="help">View submissions in the event workspace.</p><a class="quiet-button" href="/admin.php?section=submissions&amp;event_id='.(int)$event['id'].'">Open collected responses ↗</a>';
    ?></section></div>
    <div id="workspace-settings" role="tabpanel" aria-labelledby="workspace-settings-tab" data-workspace-pane="settings" hidden><section class="form-builder-header"><h2>Settings</h2><?php if($phase==='registration')st_form_prices108($tickets);st_form_settings_editor($fields,$phase); ?><label class="field"><span>Submit button text</span><input name="<?= $phase ?>_button" maxlength="200" value="<?= e($fields[$phase.'_button']??'Submit for approval') ?>"></label><p class="help">Event dates and publication status also control availability.</p></section></div>
    <template id="<?= $phase ?>-field-template"><?php st_registration_field_row('INDEX',[],$phase,$games,$joystick,$media,$tickets); ?></template>
    <p class="form-builder-status" data-builder-status role="status" aria-live="polite"></p>
    </main><dialog class="form-preview-dialog" data-form-preview-dialog aria-labelledby="form-preview-title"><div class="form-preview-top"><span>Participant preview · current draft</span><button class="quiet-button" type="button" data-preview-close aria-label="Close form preview">Close ×</button></div><div data-preview-body></div></dialog>
    </form>
    <?php
}

function st_registration_field_row(string $index,array $field,string $phase='registration',array $games=[],bool $joystick=false,array $media=[],array $tickets=[]): void {
    $name=($phase==='interest'?'interest_fields':'form_fields').'['.$index.']';$prefix=$phase.'-field-'.$index;
    ?>
    <article class="question-card" data-question-card data-question-name="<?= e($name) ?>">
     <div class="question-card-top"><span class="question-number sr-only" data-question-number>Question</span><button type="button" class="question-drag-handle" draggable="true" data-question-drag aria-label="Drag to reorder question" title="Drag to reorder">⠿</button><div class="question-position"><button type="button" data-question-move="up" aria-label="Move question up" title="Move question up">↑</button><button type="button" data-question-move="down" aria-label="Move question down" title="Move question down">↓</button></div></div>
     <input type="hidden" name="<?= e($name) ?>[id]" value="<?= e($field['id']??'') ?>" data-question-id>
     <div class="question-card-prompt"><label class="field" for="<?= e($prefix) ?>-label"><span>Question</span><input id="<?= e($prefix) ?>-label" name="<?= e($name) ?>[label]" value="<?= e($field['label']??'') ?>" placeholder="Untitled question" maxlength="120" required data-question-label></label>
     <label class="field" for="<?= e($prefix) ?>-type"><span>Answer type</span><select id="<?= e($prefix) ?>-type" name="<?= e($name) ?>[type]" data-question-type><?php foreach(az_form_types() as $key=>$label): ?><option value="<?= $key ?>" <?= ($field['type']??'text')===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label></div>
     <div class="question-grid-body"><div class="question-grid-rows" data-for-types="grid checkgrid"><strong>Rows</strong><textarea name="<?= e($name) ?>[rows]" rows="3" data-grid-rows-source aria-label="Grid rows"><?= e(implode("\n",$field['rows']??[])) ?></textarea><div data-grid-row-list></div><button type="button" class="question-option-add" data-grid-row-add>Add row</button></div><div class="question-options" data-question-options><strong class="question-column-heading" data-for-types="grid checkgrid">Columns</strong><label class="field" for="<?= e($prefix) ?>-options" data-options-fallback><span>Choices, one per line</span><textarea id="<?= e($prefix) ?>-options" name="<?= e($name) ?>[options]" rows="3" maxlength="6100" data-options-source><?= e(implode("\n",$field['options']??[])) ?></textarea></label><div data-option-list></div><div class="question-option-add-line"><button class="question-option-add" type="button" data-option-add hidden>Add option</button><span data-for-types="radio multiselect">or <button type="button" data-add-other>add “Other”</button></span></div><div class="question-other" data-other-preview hidden>Other: <span></span><button type="button" data-remove-other aria-label="Remove Other answer">×</button></div></div></div>
     <div class="question-scale-editor" data-for-types="scale rating"><div class="question-scale-range"><label><span class="sr-only">Scale start</span><select data-scale-key="min" aria-label="Scale start"><option value="1" <?= ($field['min']??'1')==='1'?'selected':'' ?>>1</option><option value="0" <?= ($field['min']??'1')==='0'?'selected':'' ?>>0</option></select></label><span>to</span><label><span class="sr-only">Scale end</span><select data-scale-key="max" aria-label="Scale end"><?php for($n=2;$n<=10;$n++): ?><option value="<?= $n ?>" <?= (int)($field['max']??5)===$n?'selected':'' ?>><?= $n ?></option><?php endfor; ?></select></label></div><?php foreach(['low_label'=>'Start label (optional)','high_label'=>'End label (optional)'] as $key=>$label): ?><label class="field"><span><?= $label ?></span><input name="<?= e($name.'['.$key.']') ?>" maxlength="60" value="<?= e($field[$key]??'') ?>" placeholder="Label (optional)"></label><?php endforeach; ?></div>
     <div class="question-answer-hint" data-answer-hint hidden></div>
     <div class="question-more-content" data-question-more hidden><details class="question-settings" open><summary>Description and answer settings</summary><div class="form-grid">
      <label class="field"><span>Description</span><textarea name="<?= e($name) ?>[help]" maxlength="2000" rows="2" data-question-help><?= e($field['help']??'') ?></textarea></label>
      <label class="field" data-for-types="text textarea email tel number"><span>Placeholder</span><input name="<?= e($name) ?>[placeholder]" value="<?= e($field['placeholder']??'') ?>" maxlength="120" data-question-placeholder></label>
      <?php if($joystick): ?><label class="field wide"><span>Show for game</span><select name="<?= e($name) ?>[game]" data-question-game><option value="">All Joystick games</option><?php foreach($games as $game): ?><option value="<?= e($game['id']) ?>" <?= ($field['game']??'')===$game['id']?'selected':'' ?>><?= e($game['label']) ?></option><?php endforeach; ?></select><small>Save new games first, then assign questions to them.</small></label><?php else: ?><input type="hidden" name="<?= e($name) ?>[game]" value=""><?php endif; ?>
      <label class="field wide" data-for-types="text textarea email tel number radio multiselect select"><span>Accepted values, one per line (optional)</span><textarea name="<?= e($name) ?>[allowed_values]" rows="3" maxlength="20000"><?= e(implode("\n",$field['allowed_values']??[])) ?></textarea><small>For issued team IDs, choose Short answer to retain leading zeros. Leave blank to accept any valid answer. This list is checked privately on the server.</small></label>
     </div></details>
     <?php st_form_question_settings($name,$field,$media,$tickets); ?></div>
     <div class="question-card-footer"><div class="question-actions"><button type="button" data-question-duplicate title="Duplicate" aria-label="Duplicate question"><?= st_form_icon('duplicate') ?></button><button type="button" data-question-delete title="Delete" aria-label="Delete question"><?= st_form_icon('delete') ?></button></div><label class="question-required"><span data-required-label>Required</span><input type="checkbox" name="<?= e($name) ?>[required]" value="1" <?= ($field['required']??true)?'checked':'' ?> data-question-required><span class="question-switch" aria-hidden="true"></span></label><button type="button" data-question-more-toggle aria-expanded="false" aria-label="More question settings" title="More question settings"><?= st_form_icon('more') ?></button></div>
    </article>
    <?php
}
